54	// ------------------------------------------------------------------ Wi-Fi connection with mobile hotspot priority
55	// Scans for all networks, prioritizes mobile hotspots, then falls back to configured networks
56	bool connectToWifiWithPriority() {
57	  Serial.println("[wifi] Scanning for available networks...");
58	
59	  // Scan for networks (non-blocking, ~3 seconds)
60	  int n = WiFi.scanNetworks();
61	
62	  if (n == 0) {
63	    Serial.println("[wifi] No networks found");
64	    return false;
65	  }
66	
67	  Serial.printf("[wifi] Found %d networks\n", n);
68	
69	  // Collect and categorize networks
70	  std::vector<WifiNetwork> allNetworks;
71	  std::vector<WifiNetwork> mobileHotspots;
72	  std::vector<WifiNetwork> stationaryNetworks;
73	
74	  for (int i = 0; i < n; ++i) {
75	    WifiNetwork net;
76	    net.ssid = WiFi.SSID(i);
77	    net.rssi = WiFi.RSSI(i);
78	    net.isMobileHotspot = isMobileHotspotSSID(net.ssid);
79	    allNetworks.push_back(net);
80	
81	    if (net.isMobileHotspot) {
82	      mobileHotspots.push_back(net);
83	      Serial.printf("[wifi] Mobile hotspot detected: %s (RSSI: %d)\n", net.ssid.c_str(), net.rssi);
84	    } else {
85	      stationaryNetworks.push_back(net);
86	      Serial.printf("[wifi] Stationary network: %s (RSSI: %d)\n", net.ssid.c_str(), net.rssi);
87	    }
88	  }
89	
90	  // Priority 1: Connect to strongest mobile hotspot with valid credentials
91	  if (MOBILE_HOTSPOT_ENABLED && mobileHotspots.size() > 0) {
92	    // Sort mobile hotspots by RSSI (strongest first)
93	    for (size_t i = 0; i < mobileHotspots.size(); ++i) {
94	      for (size_t j = i + 1; j < mobileHotspots.size(); ++j) {
95	        if (mobileHotspots[j].rssi > mobileHotspots[i].rssi) {
96	          std::swap(mobileHotspots[i], mobileHotspots[j]);
97	        }
98	      }
99	    }
100	
101	    // Try each mobile hotspot (strongest first)
102	    for (auto& net : mobileHotspots) {
103	      if (tryConnectToWifi(net.ssid, MOBILE_HOTSPOT_PASS)) {
104	        Serial.printf("[wifi] Connected to mobile hotspot: %s\n", net.ssid.c_str());
105	        return true;
106	      }
107	    }
108	    Serial.println("[wifi] Mobile hotspot found but authentication failed");
109	  }
110	
111	  // Priority 2: Connect to configured primary network (stationary)
112	  if (strlen(WIFI_SSID) > 0) {
113	    Serial.printf("[wifi] Trying configured network: %s\n", WIFI_SSID);
114	    if (tryConnectToWifi(String(WIFI_SSID), String(WIFI_PASS))) {
115	      Serial.printf("[wifi] Connected to configured network: %s\n", WIFI_SSID);
116	      return true;
117	    }
118	  }
119	
120	  // Priority 3: Try secondary configured network if available
121	  if (strlen(WIFI_SSID_2) > 0) {
122	    Serial.printf("[wifi] Trying secondary network: %s\n", WIFI_SSID_2);
123	    if (tryConnectToWifi(String(WIFI_SSID_2), String(WIFI_PASS_2))) {
124	      Serial.printf("[wifi] Connected to secondary network: %s\n", WIFI_SSID_2);
125	      return true;
126	    }
127	  }
128	
129	  // Priority 4: Try tertiary configured network if available
130	  if (strlen(WIFI_SSID_3) > 0) {
131	    Serial.printf("[wifi] Trying tertiary network: %s\n", WIFI_SSID_3);
132	    if (tryConnectToWifi(String(WIFI_SSID_3), String(WIFI_PASS_3))) {
133	      Serial.printf("[wifi] Connected to tertiary network: %s\n", WIFI_SSID_3);
134	      return true;
135	    }
136	  }
137	
138	  // Priority 5: Try strongest available stationary network (fallback)
139	  if (stationaryNetworks.size() > 0) {
140	    // Sort stationary networks by RSSI (strongest first)
141	    for (size_t i = 0; i < stationaryNetworks.size(); ++i) {
142	      for (size_t j = i + 1; j < stationaryNetworks.size(); ++j) {
143	        if (stationaryNetworks[j].rssi > stationaryNetworks[i].rssi) {
144	          std::swap(stationaryNetworks[i], stationaryNetworks[j]);
145	        }
146	      }
147	    }
148	
149	    // Try strongest stationary network first (no credentials - will use saved config)
150	    Serial.printf("[wifi] Trying strongest available: %s\n", stationaryNetworks[0].ssid.c_str());
151	    if (tryConnectToWifi(stationaryNetworks[0].ssid, "")) {
152	      Serial.printf("[wifi] Connected to strongest available: %s\n", stationaryNetworks[0].ssid.c_str());
153	      return true;
154	    }
155	  }
156	
157	  Serial.println("[wifi] All connection attempts failed");
158	  return false;
159	}
