161	// Helper function to try connecting to a specific network
162	bool tryConnectToWifi(const String& ssid, const String& password) {
163	  WiFi.disconnect();
164	  delay(100);
165	
166	  if (password.length() > 0) {
167	    WiFi.begin(ssid.c_str(), password.c_str());
168	  } else {
169	    WiFi.begin(ssid.c_str());
170	  }
171	
172	  uint32_t t0 = millis();
173	  while (WiFi.status() != WL_CONNECTED && millis() - t0 < 5000) {
174	    delay(100);
175	    // Check for unexpected disconnection
176	    if (WiFi.status() == WL_DISCONNECTED) break;
177	  }
178	
179	  bool connected = (WiFi.status() == WL_CONNECTED);
180	  if (connected) {
181	    WiFi.setAutoReconnect(true);
182	  }
183	
184	  return connected;
185	}
