244	static bool fetchQuotes() {
245	  if (WiFi.status() != WL_CONNECTED) return false;
246	  WiFiClientSecure cli;
247	  cli.setInsecure();
248	  HTTPClient http;
249	  http.setTimeout(10000);
250	  http.setFollowRedirects(HTTPC_STRICT_FOLLOW_REDIRECTS);
251	  if (!http.begin(cli, API_URL)) return false;
252	  int code = http.GET();
253	  if (code != 200) {
254	    Serial.printf("[api] HTTP %d\n", code);
255	    http.end();
256	    return false;
257	  }
258	  String body = http.getString();
259	  http.end();
260	  JsonDocument doc;
261	  if (deserializeJson(doc, body)) return false;
262	
263	  int added = 0;
264	  auto parseOne = [&](JsonVariantConst o) {
265	    Quote q;
266	    q.idx = jstr(o, "idx");
267	    q.content = jstr(o, "content", "main_content");
268	    if (q.content.length() == 0) return;
269	    q.context = jstr(o, "context");
270	    q.date = jstr(o, "date", "effectiveDate");
271	    q.specific = jstr(o, "specific", "specificName");
272	    q.container = jstr(o, "container", "containerName");
273	    q.cat = jstr(o, "cat", "category");
274	    JsonVariantConst tg = o["tags"].isNull() ? o["hashtagThemes"] : o["tags"];
275	    if (tg.is<JsonArrayConst>()) {
276	      for (JsonVariantConst t : tg.as<JsonArrayConst>()) {
277	        String s = t.as<String>();
278	        if (!s.startsWith("#")) s = "#" + s;
279	        q.tags.push_back(s);
280	      }
281	    }
282	    // Prevent duplicate quote entries in RAM
283	    for (const auto& existing : quotes) {
284	      if (existing.idx == q.idx) return;
285	    }
286	    quotes.push_back(q);
287	    added++;
288	  };
289	
290	  if (doc.is<JsonArray>()) for (JsonVariantConst o : doc.as<JsonArray>()) parseOne(o);
291	  else parseOne(doc.as<JsonVariantConst>());
292	
293	  // Purge temporary offline standby card once genuine cloud quotes are received
294	  if (added > 0 && !quotes.empty() && quotes[0].idx == "!") {
295	    quotes.erase(quotes.begin());
296	  }
297	
298	  // Limit pool size in RAM to max 20 quotes to bound heap consumption
299	  while (quotes.size() > 20) {
300	    quotes.erase(quotes.begin());
301	  }
302	
303	  Serial.printf("[api] Cloudflare stream: +%d quotes (RAM pool: %d)\n", added, (int)quotes.size());
304	  return added > 0;
305	}
