307	// ------------------------------------------------------------------ utf-8
308	static std::u16string u8to16(const String& s) {
309	  std::u16string o;
310	  const uint8_t* p = (const uint8_t*)s.c_str();
311	  size_t n = s.length();
312	  for (size_t i = 0; i < n;) {
313	    uint8_t c = p[i];
314	    uint32_t cp;
315	    int len;
316	    if (c < 0x80) { cp = c; len = 1; }
317	    else if ((c >> 5) == 6) { cp = c & 0x1F; len = 2; }
318	    else if ((c >> 4) == 14) { cp = c & 0x0F; len = 3; }
319	    else if ((c >> 3) == 30) { cp = c & 0x07; len = 4; }
320	    else { i++; continue; }
321	    if (i + len > n) break;
322	    for (int k = 1; k < len; k++) cp = (cp << 6) | (p[i + k] & 0x3F);
323	    i += len;
324	    o.push_back(cp > 0xFFFF ? u'?' : (char16_t)cp);
325	  }
326	  return o;
327	}
