333	static bool isWS(char16_t c) { return c == ' ' || c == '\t' || c == '\r' || c == 0xA0; }
334	
335	static void tokenize(const std::u16string& s, std::vector<std::u16string>& tok) {
336	  std::u16string w;
337	  auto flush = [&]() { if (!w.empty()) { tok.push_back(w); w.clear(); } };
338	  for (char16_t c : s) {
339	    if (c == '\n') { flush(); tok.push_back(u"\n"); }
340	    else if (isWS(c)) flush();
341	    else w.push_back(c);
342	  }
343	  flush();
344	}
345	
346	static std::u16string trim16(const std::u16string& s) {
347	  size_t a = 0, b = s.size();
348	  while (a < b && (isWS(s[a]) || s[a] == '\n')) a++;
349	  while (b > a && (isWS(s[b - 1]) || s[b - 1] == '\n')) b--;
350	  return s.substr(a, b - a);
351	}
