358	static std::vector<Page> buildPages(const Quote& q) {
359	  std::vector<Page> pages;
360	  std::u16string content = trim16(u8to16(q.content));
361	  if (content.empty()) { pages.push_back({{{u"", false}}, false}); return pages; }
362	  std::vector<std::u16string> tok;
363	  tokenize(content, tok);
364	  bool writing = isWriting(q.cat);
365	  size_t ti = 0;
366	  int pageNum = 0;
367	  while (ti < tok.size()) {
368	    pageNum++;
369	    bool first = pageNum == 1;
370	    std::vector<std::u16string> pl;
371	    for (int ln = 1; ln <= MAX_LINES && ti < tok.size(); ln++) {
372	      int budget = MAX_CHARS;
373	      if (first && ln == 1) budget = MAX_CHARS - 1;
374	      if (ln == MAX_LINES) budget = MAX_CHARS - 4;
375	      std::u16string cur;
376	      while (ti < tok.size()) {
377	        const std::u16string& nt = tok[ti];
378	        if (nt == u"\n") { ti++; break; }
379	        if (cur.empty()) { cur = nt; ti++; }
380	        else if ((int)(cur.size() + 1 + nt.size()) <= budget) { cur += u" "; cur += nt; ti++; }
381	        else break;
382	      }
383	      pl.push_back(cur);
384	    }
385	    size_t la = ti;
386	    while (la < tok.size() && tok[la] == u"\n") la++;
387	    bool more = la < tok.size();
388	    if (first && !pl.empty()) pl[0] = u"\u201C" + pl[0];
389	    if (more) pl.back() += u"...";
390	    else pl.back() += u"\u201D";
391	    Page pg; pg.ctx = false;
392	    for (size_t i = 0; i < pl.size(); i++) {
393	      bool terminal = !more && i == pl.size() - 1;
394	      bool just = writing && !terminal && pl[i].find(u' ') != std::u16string::npos;
395	      if (!trim16(pl[i]).empty()) pg.lines.push_back({pl[i], just});
396	    }
397	    pages.push_back(pg);
398	  }
399	  // context pages
400	  if (q.context.length() > 0) {
401	    std::vector<std::u16string> cw;
402	    tokenize(u8to16(q.context), cw);
403	    size_t ci = 0;
404	    bool firstCtx = true;
405	    while (ci < cw.size()) {
406	      std::vector<std::u16string> cl;
407	      for (int l = 1; l <= MAX_LINES && ci < cw.size(); l++) {
408	        int budget = (l == MAX_LINES) ? MAX_CHARS - 4 : MAX_CHARS;
409	        std::u16string cur;
410	        if (firstCtx && l == 1) { cur = u"[Note] "; firstCtx = false; }
411	        while (ci < cw.size()) {
412	          if (cw[ci] == u"\n") { ci++; continue; }
413	          if (cur.empty()) { cur = cw[ci]; ci++; }
414	          else if ((int)(cur.size() + 1 + cw[ci].size()) <= budget || cur == u"[Note] ") {
415	            if (cur != u"[Note] ") cur += u" ";
416	            cur += cw[ci]; ci++;
417	          } else break;
418	        }
419	        cl.push_back(cur);
420	      }
421	      if (ci < cw.size() && !cl.empty()) cl.back() += u"...";
422	      Page pg; pg.ctx = true;
423	      for (auto& s : cl) {
424	        if (!trim16(s).empty()) pg.lines.push_back({s, false});
425	      }
426	      if (!pg.lines.empty()) pages.push_back(pg);
427	    }
428	  }
429	  return pages;
430	}
