441	static uint16_t hsl565(float h, float s, float l) {
442	  h = fmodf(h, 360.f); if (h < 0) h += 360.f;
443	  float c = (1 - fabsf(2 * l - 1)) * s;
444	  float x = c * (1 - fabsf(fmodf(h / 60.f, 2) - 1));
445	  float m = l - c / 2, r = 0, g = 0, b = 0;
446	  if (h < 60) { r = c; g = x; }
447	  else if (h < 120) { r = x; g = c; }
448	  else if (h < 180) { g = c; b = x; }
449	  else if (h < 240) { g = x; b = c; }
450	  else if (h < 300) { r = x; b = c; }
451	  else { r = c; b = x; }
452	  return rgb565((r + m) * 255, (g + m) * 255, (b + m) * 255);
453	}
