455	static float tagHue(const String& tag, int idx) {
456	  int32_t hash = 0;
457	  for (size_t i = 0; i < tag.length(); i++)
458	    hash = (int32_t)((((uint32_t)hash << 5) - (uint32_t)hash) + (uint8_t)tag[i]);
459	  return fabsf(floorf(fmodf((float)((double)hash * 137.508 + idx * 89), 360.f)));
460	}
