474	static void drawHeader(const Quote& q, bool busy) {
475	  cv.h = HDR_H;
476	  cv.fill(C_BLACK);
477	  cv.rect(0, HDR_H - 1, SW, 1, C_RULE);
478	  const int base = 14;
479	  std::u16string date = u8to16(q.date.length() ? q.date : String("—"));
480	  int dateW = fSB10.adv * (int)date.size();
481	  int labelW = fSB10.adv * 5;
482	  int rightW = labelW + 4 + dateW;
483	  int rx = SW - 12 - rightW;
484	  cv.text(fSB10, rx, base, u"Date:", C_DIM);
485	  cv.text(fSB10, rx + labelW + 4, base, date, C_GHOST);
486	  int x = 12;
487	  if (busy) {
488	    cv.text(fSB10, x, base, u"// Receiving prescript...", C_GHOST);
489	  } else {
490	    std::u16string idx = u"#" + u8to16(q.idx);
491	    x += cv.text(fBD13, x, base, idx, C_GHOST) + 4;
492	    x += cv.text(fSB10, x, base, u"~", C_SEP) + 4;
493	    std::u16string title = u8to16(q.specific);
494	    int avail = rx - 8 - x;
495	    int maxCh = avail / fSB10.adv;
496	    if ((int)title.size() > maxCh && maxCh > 1) title = title.substr(0, maxCh - 1) + u"\u2026";
497	    cv.text(fSB10, x, base, title, C_TITLE, avail);
498	  }
499	  push(0, HDR_H);
500	}
