502	static void drawFooter(const Quote& q, int seed = 0) {
503	  cv.h = FTR_H;
504	  cv.fill(C_BLACK);
505	  cv.rect(0, 0, SW, 1, C_RULE);
506	  uint16_t accent = accentFor(q);
507	  const int base = 15;
508	  std::u16string cont = u8to16(q.container);
509	  int contMax = 150 / fSB10.adv;
510	  if ((int)cont.size() > contMax) cont = cont.substr(0, contMax - 1) + u"\u2026";
511	  int contW = fSB10.adv * (int)cont.size();
512	  int cx = SW - 12 - contW;
513	  cv.text(fBD13, cx, base, cont, accent);
514	  int x = 12;
515	  for (size_t i = 0; i < q.tags.size(); i++) {
516	    std::u16string t = u8to16(q.tags[i]);
517	    int w = fSB9.adv * (int)t.size() + 10 + 2;
518	    if (x + w > cx - 8) break;
519	    float hue = tagHue(q.tags[i], (int)i) + seed;
520	    uint16_t tcol = hsl565(hue, 0.90f, 0.80f), bg = hsl565(hue, 0.65f, 0.12f);
521	    uint16_t bd = mix565(C_BLACK, hsl565(hue, 0.75f, 0.50f), 140);
522	    const int y0 = 4, hh = 15;
523	    cv.rect(x, y0, w, hh, bd);
524	    cv.rect(x + 1, y0 + 1, w - 2, hh - 2, bg);
525	    cv.b[y0 * cv.w + x] = C_BLACK; cv.b[y0 * cv.w + x + w - 1] = C_BLACK;
526	    cv.b[(y0 + hh - 1) * cv.w + x] = C_BLACK; cv.b[(y0 + hh - 1) * cv.w + x + w - 1] = C_BLACK;
527	    cv.text(fSB9, x + 6, y0 + 11, t, tcol);
528	    x += w + 4;
529	  }
530	  push(SH - FTR_H, FTR_H);
531	}
