546	static void drawBodyLineFinal(const Line& ln, int y, bool ctx, uint16_t accent) {
547	  cv.h = 20;
548	  cv.fill(ctx ? C_BOXBG : C_BLACK);
549	  const VFont& fn = fBD13;
550	  int base = (20 - (fn.ascent + fn.descent)) / 2 + fn.ascent;
551	  int cellW = fn.adv;
552	  int x0 = ctx ? 16 : 16;
553	  if (ctx) cv.rect(8, 0, 3, 20, accent);
554	  const std::u16string& s = ln.t;
555	  std::vector<int> xs(s.size());
556	  int spaces = 0;
557	  for (char16_t c : s) if (c == ' ') spaces++;
558	  if (ln.just && spaces > 0) {
559	    int W = MAX_CHARS * cellW;
560	    int gap = W - (int)(s.size() - spaces) * cellW;
561	    int extra = gap - spaces * 0;
562	    int per = extra / spaces, rem = extra % spaces, x = x0, sp = 0;
563	    for (size_t i = 0; i < s.size(); i++) {
564	      xs[i] = x;
565	      if (s[i] == ' ') x += per + (sp++ < rem ? 1 : 0);
566	      else x += cellW;
567	    }
568	  } else {
569	    for (size_t i = 0; i < s.size(); i++) xs[i] = x0 + (int)i * cellW;
570	  }
571	  for (size_t i = 0; i < s.size(); i++) {
572	    char16_t c = s[i];
573	    if (c == ' ') continue;
574	    if (ctx) {
575	      if (i < 6 && s.size() >= 6 && s.substr(0, 6) == u"[Note]") {
576	        cv.drawChar(fBD13, xs[i], base, c, accent, true); // Bilevel 1-bit crisp
577	      } else {
578	        cv.drawChar(fBD13, xs[i], base, c, C_WHITE, true);  // Bilevel 1-bit crisp
579	      }
580	    } else {
581	      if (c == 0x201C || c == 0x201D || c == '.') cv.drawChar(fBD13, xs[i], base, c, accent);
582	      else cv.drawChar(fn, xs[i], base, c, C_WHITE);
583	    }
584	  }
585	  push(y, 20);
586	}
