594	// ------------------------------------------------------------------ entropy animation
595	struct Cell { char16_t target, cur; uint32_t life, nextScr; bool locked; };
596	static Cell grid[MAX_LINES][MAX_CHARS + 8];
597	static int gridLen[MAX_LINES];
598	static const char SCRAMBLE[] = "ABCDEF@HIJ_LM%OPQR^WX#YZa#b+cdefgh*iqrxyz0123456789!$*+=-~?/";
599	static char16_t rndCipher() { return SCRAMBLE[random(sizeof(SCRAMBLE) - 1)]; }
