611	  animating = false;
612	  nextChime = 0xFFFFFFFF;
613	  Serial.printf("[anim] FINISH at %u ms (%u frames, playChime=%d)\n", millis() - animStart, animFrameCount, playChime);
614	  renderPageFinal(pages[curPage], curAccent);
615	  drawHeader(quotes[curQuote], false);
