619	static bool renderAnimationFrame(uint32_t el) {
620	  Page& pg = pages[curPage];
621	  bool all = true;
622	  int y = bodyTop((int)pg.lines.size());
623	  const int base = (20 - (fBD13.ascent + fBD13.descent)) / 2 + fBD13.ascent;
624	
625	  for (int r = 0; r < (int)pg.lines.size() && r < MAX_LINES; r++) {
626	    cv.h = 20;
627	    cv.fill(C_BLACK);
628	    for (int c = 0; c < gridLen[r]; c++) {
629	      Cell& ce = grid[r][c];
630	      if (!ce.locked) {
631	        if (el >= ce.life) {
632	          ce.locked = true;
633	          ce.cur = ce.target;
634	        } else {
635	          all = false;
636	          // Active continuous cipher scramble on every frame
637	          ce.cur = rndCipher();
638	        }
639	      }
640	      int x = 16 + c * fBD13.adv;
641	      if (ce.locked) {
642	        if (ce.target == ' ') continue;
643	        if (ce.target == 0x201C || ce.target == 0x201D || ce.target == '.')
644	          cv.drawChar(fBD13, x, base, ce.target, curAccent);
645	        else
646	          cv.drawChar(fBD13, x, base, ce.target, C_WHITE);
647	      } else {
648	        cv.drawChar(fBD13, x, base, ce.cur, C_WHITE);
649	      }
650	    }
651	    push(y + r * LINE_PITCH, 20);
652	  }
653	  return all;
654	}
