656	static void showPage(bool animate, bool sound) {
657	  const Quote& q = quotes[curQuote];
658	  curAccent = accentFor(q);
659	  Page& pg = pages[curPage];
660	  drawFooter(q);
661	  if (!animate || pg.ctx) {
662	    animating = false;
663	    nextChime = 0xFFFFFFFF;
664	    drawHeader(q, false);
665	    renderPageFinal(pg, curAccent);
666	    if (sound) jqPlay(TRACK_COMPLETE);
667	    return;
668	  }
669	  drawHeader(q, true);
670	  clearBody();
671	  uint32_t total = max<uint32_t>(900, ENTROPY_MS * 35);
672	  for (int r = 0; r < (int)pg.lines.size() && r < MAX_LINES; r++) {
673	    const std::u16string& s = pg.lines[r].t;
674	    gridLen[r] = min<int>((int)s.size(), MAX_CHARS + 8);
675	    for (int c = 0; c < gridLen[r]; c++)
676	      grid[r][c] = {s[c], rndCipher(), (uint32_t)random(total), (uint32_t)random(40), false};
677	  }
678	  animating = true;
679	  animFrameCount = 0;
680	  Serial.printf("[anim] START Quote #%s (total=%u ms)\n", q.idx.c_str(), total);
681	
682	  // Instantly render Frame 0 of scramble — zero black void
683	  renderAnimationFrame(0);
684	
685	  if (sound) jqPlay(TRACK_DRAW);
686	
687	  // Time base begins strictly after initial frame is dispatched to screen
688	  animStart = millis();
689	  lastFrame = animStart;
690	}
