796	struct Btn {
797	  uint8_t pin;
798	  bool latched = false;
799	  uint32_t highSince = 0;
800	
801	  bool pressed() {
802	    bool reading = digitalRead(pin);
803	    uint32_t now = millis();
804	
805	    if (reading == LOW) {
806	      highSince = 0;
807	      if (!latched) {
808	        latched = true;
809	        return true; // 0ms instantaneous response on press
810	      }
811	    } else {
812	      if (latched) {
813	        if (highSince == 0) {
814	          highSince = now;
815	        } else if (now - highSince >= 50) {
816	          // Stably released for 50ms, release latch (handles internal ~45k pull-up rise time)
817	          latched = false;
818	          highSince = 0;
819	        }
820	      }
821	    }
822	    return false;
823	  }
824	};
