894	void loop() {
895	  // Serial command interface for remote manual triggering
896	  if (Serial.available()) {
897	    char ch = Serial.read();
898	    if (ch == 'r' || ch == 'R') {
899	      Serial.println("[SIM] ROLL trigger");
900	      rollQuote();
901	      return;
902	    }
903	    if (ch == 's' || ch == 'S' || ch == 'p' || ch == 'P') {
904	      Serial.println("[SIM] SCROLL / PAGE trigger");
905	      changePage();
906	      return;
907	    }
908	    if (ch == 'c' || ch == 'C' || ch == 'w' || ch == 'W') {
