910	      if (WiFi.status() != WL_CONNECTED) {
911	        Serial.printf("[wifi] Connecting to %s...\n", WIFI_SSID);
912	        WiFi.begin(WIFI_SSID, WIFI_PASS);
913	        uint32_t t0 = millis();
914	        while (WiFi.status() != WL_CONNECTED && millis() - t0 < 8000) delay(200);
915	      }
916	      if (WiFi.status() == WL_CONNECTED) {
917	        Serial.printf("[wifi] Connected: %s\n", WiFi.localIP().toString().c_str());
918	        fetchQuotes();
919	      } else {
920	        Serial.printf("[wifi] Status: %d\n", WiFi.status());
921	      }
922	      return;
923	    }
924	  }
925	
926	  // Physical button checks (100% manual control)
927	  if (btnRoll.pressed() || btnRollAlt.pressed()) {
928	    Serial.println("[btn] ROLL");
929	    rollQuote();
930	    return;
931	  }
932	  if (btnScroll.pressed()) {
933	    Serial.println("[btn] SCROLL");
934	    changePage();
935	    return;
936	  }
937	
938	  if (animating) {
939	    stepAnimation();
940	  } else if (WiFi.status() == WL_CONNECTED) {
941	    // Background cloud sync every 15 minutes when idle
942	    static uint32_t lastApiRefresh = 0;
943	    if (millis() - lastApiRefresh > 15UL * 60 * 1000) {
944	      lastApiRefresh = millis();
945	      fetchQuotes();
946	    }
947	  }
948	
949	  // Pure manual mode: NO auto-page, NO auto-reroll!
950	  delay(1);
951	}
