static const uint16_t C_GHOST = rgb565(0xcc, 0xcc, 0xcc), C_TITLE = rgb565(0xee, 0xee, 0xee);
static const uint16_t C_DIM = rgb565(0xaa, 0xaa, 0xaa), C_SEP = rgb565(0x77, 0x77, 0x77);
static const uint16_t C_RULE = rgb565(0x33, 0x33, 0x33);
static const uint16_t C_BOXBG = rgb565(0x0a, 0x0a, 0x0a);
static const uint16_t ACCENTS[4] = {rgb565(0x38, 0xbd, 0xf8), rgb565(0xf5, 0x9e, 0x0b),
                                    rgb565(0x10, 0xb9, 0x81), rgb565(0xf4, 0x3f, 0x5e)};

